#import "SAConsoleController.h"
#import "SAAPIStore.h"
@interface SAConsoleController ()
@property UITextField *phoneField; @property UITextField *roundField; @property UIButton *runButton; @property UILabel *statusLabel; @property UITextView *logView; @property UIProgressView *progress; @property BOOL running; @property NSUInteger generation;
@end
@implementation SAConsoleController
- (void)viewDidLoad { [super viewDidLoad]; self.title=@"接口控制台"; self.view.backgroundColor=UIColor.systemGroupedBackgroundColor; [self buildUI]; [self resetLog]; }
- (UILabel *)label:(NSString *)text size:(CGFloat)size weight:(UIFontWeight)weight { UILabel*l=[UILabel new];l.text=text;l.font=[UIFont systemFontOfSize:size weight:weight];l.textColor=UIColor.labelColor;l.translatesAutoresizingMaskIntoConstraints=NO;return l; }
- (UIView *)card { UIView*v=[UIView new];v.backgroundColor=UIColor.secondarySystemGroupedBackgroundColor;v.layer.cornerRadius=16;v.translatesAutoresizingMaskIntoConstraints=NO;return v; }
- (void)buildUI { UIScrollView*scroll=[UIScrollView new];scroll.translatesAutoresizingMaskIntoConstraints=NO;UIView*body=[UIView new];body.translatesAutoresizingMaskIntoConstraints=NO;[self.view addSubview:scroll];[scroll addSubview:body];
 UILabel*title=[self label:@"📱 API 接口控制台" size:25 weight:UIFontWeightBold];UILabel*sub=[self label:[NSString stringWithFormat:@"%@ 个接口 · 参数预演与结构校验",[SAAPIStore shared].statistics[@"total"]] size:15 weight:UIFontWeightRegular];sub.textColor=UIColor.secondaryLabelColor;
 UIView*input=[self card];self.phoneField=[UITextField new];self.phoneField.placeholder=@"输入测试号码（仅用于本地占位替换）";self.phoneField.keyboardType=UIKeyboardTypePhonePad;self.phoneField.borderStyle=UITextBorderStyleRoundedRect;self.phoneField.clearButtonMode=UITextFieldViewModeWhileEditing;self.phoneField.translatesAutoresizingMaskIntoConstraints=NO;self.phoneField.delegate=self;
 UILabel*roundLabel=[self label:@"轮数" size:17 weight:UIFontWeightMedium];self.roundField=[UITextField new];self.roundField.text=@"1";self.roundField.keyboardType=UIKeyboardTypeNumberPad;self.roundField.textAlignment=NSTextAlignmentCenter;self.roundField.borderStyle=UITextBorderStyleRoundedRect;self.roundField.translatesAutoresizingMaskIntoConstraints=NO;
 self.runButton=[UIButton buttonWithType:UIButtonTypeSystem];[self.runButton setTitle:@"开始本地预演" forState:UIControlStateNormal];self.runButton.titleLabel.font=[UIFont systemFontOfSize:19 weight:UIFontWeightSemibold];self.runButton.backgroundColor=UIColor.systemBlueColor;[self.runButton setTitleColor:UIColor.whiteColor forState:UIControlStateNormal];self.runButton.layer.cornerRadius=12;self.runButton.translatesAutoresizingMaskIntoConstraints=NO;[self.runButton addTarget:self action:@selector(runTapped) forControlEvents:UIControlEventTouchUpInside];
 self.statusLabel=[self label:@"准备就绪" size:15 weight:UIFontWeightMedium];self.statusLabel.textColor=UIColor.systemBlueColor;self.statusLabel.textAlignment=NSTextAlignmentCenter;self.progress=[UIProgressView new];self.progress.translatesAutoresizingMaskIntoConstraints=NO;
 UIView*logCard=[self card];self.logView=[UITextView new];self.logView.editable=NO;self.logView.selectable=YES;self.logView.backgroundColor=UIColor.clearColor;self.logView.textColor=UIColor.labelColor;self.logView.font=[UIFont monospacedSystemFontOfSize:13 weight:UIFontWeightRegular];self.logView.translatesAutoresizingMaskIntoConstraints=NO;[logCard addSubview:self.logView];
 UIButton*clear=[UIButton buttonWithType:UIButtonTypeSystem];[clear setTitle:@"清空日志" forState:UIControlStateNormal];clear.translatesAutoresizingMaskIntoConstraints=NO;[clear addTarget:self action:@selector(resetLog) forControlEvents:UIControlEventTouchUpInside];UIButton*copy=[UIButton buttonWithType:UIButtonTypeSystem];[copy setTitle:@"复制日志" forState:UIControlStateNormal];copy.translatesAutoresizingMaskIntoConstraints=NO;[copy addTarget:self action:@selector(copyLog) forControlEvents:UIControlEventTouchUpInside];UIStackView*actions=[[UIStackView alloc]initWithArrangedSubviews:@[clear,copy]];actions.axis=UILayoutConstraintAxisHorizontal;actions.distribution=UIStackViewDistributionFillEqually;actions.translatesAutoresizingMaskIntoConstraints=NO;
 for(UIView*v in @[title,sub,input,self.runButton,self.statusLabel,self.progress,logCard,actions])[body addSubview:v];for(UIView*v in @[self.phoneField,roundLabel,self.roundField])[input addSubview:v];
 [NSLayoutConstraint activateConstraints:@[[scroll.topAnchor constraintEqualToAnchor:self.view.safeAreaLayoutGuide.topAnchor],[scroll.leadingAnchor constraintEqualToAnchor:self.view.leadingAnchor],[scroll.trailingAnchor constraintEqualToAnchor:self.view.trailingAnchor],[scroll.bottomAnchor constraintEqualToAnchor:self.view.bottomAnchor],[body.topAnchor constraintEqualToAnchor:scroll.contentLayoutGuide.topAnchor],[body.leadingAnchor constraintEqualToAnchor:scroll.contentLayoutGuide.leadingAnchor],[body.trailingAnchor constraintEqualToAnchor:scroll.contentLayoutGuide.trailingAnchor],[body.bottomAnchor constraintEqualToAnchor:scroll.contentLayoutGuide.bottomAnchor],[body.widthAnchor constraintEqualToAnchor:scroll.frameLayoutGuide.widthAnchor],[title.topAnchor constraintEqualToAnchor:body.topAnchor constant:22],[title.centerXAnchor constraintEqualToAnchor:body.centerXAnchor],[sub.topAnchor constraintEqualToAnchor:title.bottomAnchor constant:7],[sub.centerXAnchor constraintEqualToAnchor:body.centerXAnchor],[input.topAnchor constraintEqualToAnchor:sub.bottomAnchor constant:22],[input.leadingAnchor constraintEqualToAnchor:body.leadingAnchor constant:16],[input.trailingAnchor constraintEqualToAnchor:body.trailingAnchor constant:-16],[self.phoneField.topAnchor constraintEqualToAnchor:input.topAnchor constant:16],[self.phoneField.leadingAnchor constraintEqualToAnchor:input.leadingAnchor constant:16],[self.phoneField.trailingAnchor constraintEqualToAnchor:input.trailingAnchor constant:-16],[self.phoneField.heightAnchor constraintEqualToConstant:48],[roundLabel.topAnchor constraintEqualToAnchor:self.phoneField.bottomAnchor constant:15],[roundLabel.leadingAnchor constraintEqualToAnchor:self.phoneField.leadingAnchor],[roundLabel.bottomAnchor constraintEqualToAnchor:input.bottomAnchor constant:-16],[self.roundField.centerYAnchor constraintEqualToAnchor:roundLabel.centerYAnchor],[self.roundField.leadingAnchor constraintEqualToAnchor:roundLabel.trailingAnchor constant:15],[self.roundField.widthAnchor constraintEqualToConstant:76],[self.roundField.heightAnchor constraintEqualToConstant:42],[self.runButton.topAnchor constraintEqualToAnchor:input.bottomAnchor constant:15],[self.runButton.leadingAnchor constraintEqualToAnchor:input.leadingAnchor],[self.runButton.trailingAnchor constraintEqualToAnchor:input.trailingAnchor],[self.runButton.heightAnchor constraintEqualToConstant:54],[self.statusLabel.topAnchor constraintEqualToAnchor:self.runButton.bottomAnchor constant:12],[self.statusLabel.leadingAnchor constraintEqualToAnchor:input.leadingAnchor],[self.statusLabel.trailingAnchor constraintEqualToAnchor:input.trailingAnchor],[self.progress.topAnchor constraintEqualToAnchor:self.statusLabel.bottomAnchor constant:10],[self.progress.leadingAnchor constraintEqualToAnchor:input.leadingAnchor],[self.progress.trailingAnchor constraintEqualToAnchor:input.trailingAnchor],[logCard.topAnchor constraintEqualToAnchor:self.progress.bottomAnchor constant:16],[logCard.leadingAnchor constraintEqualToAnchor:input.leadingAnchor],[logCard.trailingAnchor constraintEqualToAnchor:input.trailingAnchor],[logCard.heightAnchor constraintEqualToConstant:260],[self.logView.topAnchor constraintEqualToAnchor:logCard.topAnchor constant:8],[self.logView.leadingAnchor constraintEqualToAnchor:logCard.leadingAnchor constant:8],[self.logView.trailingAnchor constraintEqualToAnchor:logCard.trailingAnchor constant:-8],[self.logView.bottomAnchor constraintEqualToAnchor:logCard.bottomAnchor constant:-8],[actions.topAnchor constraintEqualToAnchor:logCard.bottomAnchor constant:8],[actions.leadingAnchor constraintEqualToAnchor:input.leadingAnchor],[actions.trailingAnchor constraintEqualToAnchor:input.trailingAnchor],[actions.heightAnchor constraintEqualToConstant:44],[actions.bottomAnchor constraintEqualToAnchor:body.bottomAnchor constant:-24]]]; }
- (NSString *)stamp { NSDateFormatter*f=[NSDateFormatter new];f.dateFormat=@"HH:mm:ss";return [f stringFromDate:NSDate.date]; }
- (void)append:(NSString *)text { self.logView.text=[self.logView.text stringByAppendingFormat:@"[%@] %@\n",self.stamp,text];[self.logView scrollRangeToVisible:NSMakeRange(self.logView.text.length,0)]; }
- (void)resetLog { self.logView.text=@"";[self append:[NSString stringWithFormat:@"🔥 已加载接口 %@ 个",[SAAPIStore shared].statistics[@"total"]]];[self append:@"🛡️ 当前模式：本地参数预演，不发起网络请求"]; }
- (void)copyLog { UIPasteboard.generalPasteboard.string=self.logView.text;self.statusLabel.text=@"日志已复制"; }
- (void)runTapped { if(self.running){self.running=NO;self.generation++;self.statusLabel.text=@"已停止";[self.runButton setTitle:@"开始本地预演" forState:UIControlStateNormal];return;}NSUInteger rounds=MAX(1,MIN(10,self.roundField.text.integerValue));self.roundField.text=[NSString stringWithFormat:@"%lu",(unsigned long)rounds];self.running=YES;NSUInteger token=++self.generation;[self.runButton setTitle:@"停止预演" forState:UIControlStateNormal];[self append:[NSString stringWithFormat:@"📱 测试号码：%@",self.phoneField.text.length?@"已输入（日志已隐藏）":@"未输入，使用掩码样例"]];[self append:[NSString stringWithFormat:@"🔢 轮数：%lu",(unsigned long)rounds]];[self step:0 total:rounds token:token]; }
- (void)step:(NSUInteger)i total:(NSUInteger)n token:(NSUInteger)token { if(!self.running||token!=self.generation)return;if(i>=n){self.running=NO;self.progress.progress=1;self.statusLabel.text=@"本地预演完成";[self.runButton setTitle:@"再次本地预演" forState:UIControlStateNormal];[self append:@"✅ 全部轮次完成：JSON、占位符与请求结构已解析"];return;}self.progress.progress=(float)i/n;self.statusLabel.text=[NSString stringWithFormat:@"正在预演 %lu/%lu",(unsigned long)i+1,(unsigned long)n];dispatch_async(dispatch_get_global_queue(QOS_CLASS_USER_INITIATED,0),^{NSUInteger get=0,post=0,risk=0;for(NSDictionary*a in [SAAPIStore shared].apis){[a[@"method"]isEqual:@"POST"]?post++:get++;risk += [[SAAPIStore shared]risksForAPI:a].count>0;}dispatch_async(dispatch_get_main_queue(),^{if(token!=self.generation)return;[self append:[NSString stringWithFormat:@"⏳ 第 %lu 轮：解析 GET %lu / POST %lu / 风险 %lu",(unsigned long)i+1,(unsigned long)get,(unsigned long)post,(unsigned long)risk]];dispatch_after(dispatch_time(DISPATCH_TIME_NOW,150*NSEC_PER_MSEC),dispatch_get_main_queue(),^{[self step:i+1 total:n token:token];});});}); }
- (BOOL)textFieldShouldReturn:(UITextField*)t{[t resignFirstResponder];return YES;}
@end
